import os
import sys
import numpy as np

SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
ACT3_DIR = os.path.normpath(os.path.join(SCRIPT_DIR, "..", ".."))
DATA_DIR = os.path.join(ACT3_DIR, "data")

SIZES = [10, 100, 250, 500, 1000]
ATOL = 1e-6

def load_matrix(path):
    return np.loadtxt(path, delimiter=",")

def main():
    failures = 0

    print("=== Activity 3 validation ===")
    print(f"Data directory: {DATA_DIR}\n")

    # 1) All input matrices must exist with the right shape (generated by
    #    generate_inputsAct3.py, independent from other activities).
    for n in SIZES:
        for letter in ("A", "B"):
            path = os.path.join(DATA_DIR, f"matrix_{letter}_{n}.csv")
            if not os.path.exists(path):
                print(f"[FAIL] Missing input matrix: {path}")
                failures += 1
                continue
            m = load_matrix(path)
            if m.shape != (n, n):
                print(f"[FAIL] matrix_{letter}_{n}.csv has shape {m.shape}, expected ({n}, {n})")
                failures += 1
            else:
                print(f"[OK] matrix_{letter}_{n}.csv shape {m.shape}")

    # 2) Sequential result dumped by the C benchmark (--validate 10)
    #    checked against NumPy's reference product.
    result_path = os.path.join(DATA_DIR, "result_C_10.csv")
    if not os.path.exists(result_path):
        print(f"\n[FAIL] Result file not found: {result_path}")
        print("Run: .\\Activity3\\code\\c\\benchmark_omp.exe --validate 10")
        failures += 1
    else:
        A = load_matrix(os.path.join(DATA_DIR, "matrix_A_10.csv"))
        B = load_matrix(os.path.join(DATA_DIR, "matrix_B_10.csv"))
        C = load_matrix(result_path)
        reference = A @ B
        max_diff = np.max(np.abs(C - reference))
        if np.allclose(C, reference, atol=ATOL, rtol=0.0):
            print(f"\n[OK] C sequential (n=10) matches NumPy @ : max abs diff = {max_diff:.3e} (atol={ATOL})")
        else:
            print(f"\n[FAIL] C sequential (n=10) differs from NumPy @ : max abs diff = {max_diff:.3e}")
            failures += 1

    print()
    if failures == 0:
        print("All validation checks passed.")
        return 0
    print(f"{failures} validation check(s) FAILED.")
    return 1

if __name__ == "__main__":
    sys.exit(main())
